// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint v) public {
        vm.assume(_tos.length > 0);
        bool ok = false;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            ok = r;
        } catch {
            // revert is fine, skip
            return;
        }
        assertTrue(ok);
    }
}
